import{_ as n,C as l,o as i,c as _,ah as o,E as r,j as e,a}from"./chunks/framework.DuX8SFU5.js";const b=JSON.parse('{"title":"AM_CAN_LOGGER — руководство пользователя","description":"","frontmatter":{},"headers":[],"relativePath":"am_can_logger/user-guide.md","filePath":"am_can_logger/user-guide.md"}'),s={name:"am_can_logger/user-guide.md"};function h(g,t,c,A,p,u){const d=l("AssetImage");return i(),_("div",null,[t[0]||(t[0]=o('<h1 id="am-can-logger-—-руководство-пользователя" tabindex="-1">AM_CAN_LOGGER — руководство пользователя <a class="header-anchor" href="#am-can-logger-—-руководство-пользователя" aria-label="Permalink to &quot;AM_CAN_LOGGER — руководство пользователя&quot;">​</a></h1><h2 id="состав-комплекта" tabindex="-1">Состав комплекта <a class="header-anchor" href="#состав-комплекта" aria-label="Permalink to &quot;Состав комплекта&quot;">​</a></h2><p>В комплект входят:</p><ul><li>Контроллер <a href="https://docs.px4.io/main/en/assembly/quick_start_cuav_pixhawk_v6x" target="_blank" rel="noreferrer">CUAV Pixhawk V6X</a> с прошивкой AM_CAN_LOGGER.</li><li>Два кабеля для подключения к CAN-шинам станка: CAN_H, CAN_L и GND.</li><li>Wi-Fi-модуль <a href="https://store.cuav.net/cuav-pw-link-docs-tutorial-firmware-troubleshooting/" target="_blank" rel="noreferrer">CUAV PW-Link</a>, подключённый к порту TELEM1.</li><li>Преобразователь DC/DC для питания регистратора от бортовой сети станка.</li><li>USB-кабель для подключения к компьютеру.</li><li>Набор наклеек двустороннего скотча для крепления контроллера к раме станка.</li><li>USB-HUB с ETH и кардридером для микро SD карты</li></ul>',4)),r(d,{name:"am_can_logger_kit.webp",alt:"Комплект AM_CAN_LOGGER: контроллер, два кабеля CAN, модуль PW-Link, преобразователь питания и USB-кабель"}),t[1]||(t[1]=e("p",null,"Наклейки двустороннего скотча на фотографии не показаны.",-1)),t[2]||(t[2]=e("h3",{id:"разъемы-и-распиновка",tabindex:"-1"},[a("Разъёмы и распиновка "),e("a",{class:"header-anchor",href:"#разъемы-и-распиновка","aria-label":'Permalink to "Разъёмы и распиновка"'},"​")],-1)),t[3]||(t[3]=e("p",null,[a("PW-Link подключается к TELEM1, преобразователь питания — к POWER 1 или POWER C1, кабели шин станка — к CAN1 и CAN2. Нумерация контактов приведена по "),e("a",{href:"https://docs.px4.io/main/en/assembly/quick_start_cuav_pixhawk_v6x#pinouts",target:"_blank",rel:"noreferrer"},"схеме разъёмов CUAV Pixhawk V6X"),a(". Перед подключением сверяйте положение контакта 1 со схемой: при взгляде на ответную часть кабеля расположение контактов зеркальное.")],-1)),r(d,{name:"am_can_logger_pixhawk_v6x_pinout.webp",alt:"Распиновка разъёмов CUAV Pixhawk V6X, включая TELEM1, POWER C1, CAN1 и CAN2"}),t[4]||(t[4]=o('<table tabindex="0"><thead><tr><th>Контакт</th><th>TELEM1</th><th>POWER C1</th><th>CAN1</th><th>CAN2</th></tr></thead><tbody><tr><td>1</td><td>+5 В</td><td>+5 В, вход питания</td><td>+5 В</td><td>+5 В</td></tr><tr><td>2</td><td>TX, передача от контроллера</td><td>+5 В, вход питания</td><td>CAN1_H</td><td>CAN2_H</td></tr><tr><td>3</td><td>RX, приём контроллером</td><td>CAN_H модуля питания</td><td>CAN1_L</td><td>CAN2_L</td></tr><tr><td>4</td><td>CTS, управление потоком</td><td>CAN_L модуля питания</td><td>GND</td><td>GND</td></tr><tr><td>5</td><td>RTS, управление потоком</td><td>GND</td><td>—</td><td>—</td></tr><tr><td>6</td><td>GND</td><td>GND</td><td>—</td><td>—</td></tr></tbody></table><p>Для PW-Link используются питание +5 В, GND и линии UART: TX контроллера соединяется с RX модуля, RX контроллера — с TX модуля. К сети станка подключаются только CAN_H, CAN_L и GND; контакт +5 В разъёмов CAN1 и CAN2 к сети станка не подключается. Питание от бортовой сети подаётся через комплектный DC/DC-преобразователь; подавать бортовое напряжение напрямую на разъёмы питания контроллера нельзя.</p><h2 id="подключение-к-сети-станка" tabindex="-1">Подключение к сети станка <a class="header-anchor" href="#подключение-к-сети-станка" aria-label="Permalink to &quot;Подключение к сети станка&quot;">​</a></h2><p>Подключите вход комплектного DC/DC-преобразователя к точке бортовой сети с постоянным напряжением <strong>6–51 В</strong>, соблюдая полярность. Рекомендуется подключение через предохранитель. Выход преобразователя подключается к любому из двух разъёмов контроллера: <strong>POWER 1</strong> или <strong>POWER C1</strong>. Допускается подключать питание регистратора «на горячую», когда станок уже запитан.</p><h2 id="включение" tabindex="-1">Включение <a class="header-anchor" href="#включение" aria-label="Permalink to &quot;Включение&quot;">​</a></h2><p>Подайте питание: регистратор включится и автоматически начнёт запись логов, дополнительных действий не требуется. Для завершения работы достаточно снять питание; специальная процедура выключения не нужна.</p><h2 id="подключение-к-дэшборду" tabindex="-1">Подключение к дэшборду <a class="header-anchor" href="#подключение-к-дэшборду" aria-label="Permalink to &quot;Подключение к дэшборду&quot;">​</a></h2><h3 id="_1-получить-приложение" tabindex="-1">1. Получить приложение <a class="header-anchor" href="#_1-получить-приложение" aria-label="Permalink to &quot;1. Получить приложение&quot;">​</a></h3><p>Заранее получите у разработчика актуальное приложение <strong>AM CAN logger tools</strong> для своей системы: оно запускает сервер дэшборда, установка Python не требуется. Ниже приведены имена файлов сборки v0.5.0; у новой сборки номер версии будет другим.</p><table tabindex="0"><thead><tr><th>Система</th><th>Файл</th><th>Как запустить</th></tr></thead><tbody><tr><td>Windows 10 и новее, x64</td><td><code>am_canlog-v0.5.0-windows-x64.exe</code></td><td>Двойной щелчок, без установки.</td></tr><tr><td>Linux, x86-64</td><td><code>am_canlog-v0.5.0-linux-x64.AppImage</code></td><td>Разрешите выполнение в свойствах файла и запустите.</td></tr><tr><td>Android 7 и новее, ARM64</td><td><code>am_canlog-v0.5.0-android.apk</code></td><td>Установите APK и откройте <strong>AM CAN logger</strong>.</td></tr></tbody></table><h3 id="_2-подключиться-к-регистратору" tabindex="-1">2. Подключиться к регистратору <a class="header-anchor" href="#_2-подключиться-к-регистратору" aria-label="Permalink to &quot;2. Подключиться к регистратору&quot;">​</a></h3><p>Выберите один способ; дальнейшая работа с панелью одинакова:</p><ul><li><strong>Wi-Fi:</strong> после включения регистратора подключитесь к сети его PW-Link вида <code>CUAVWLink_XXXXXX</code> с паролем по умолчанию <code>cuavwlink</code> (если он не изменён). Если рядом несколько модулей, выберите сеть нужного регистратора. При предупреждении «Нет интернета» сохраните подключение: эта сеть нужна только для связи с устройством.</li><li><strong>USB, на компьютере:</strong> подключите комплектный USB-кабель и закройте QGroundControl и другие программы, занимающие порт регистратора. На Android используйте Wi-Fi.</li></ul>',13)),r(d,{name:"am_can_logger_pwlink_wifi.webp",alt:"Пример сетей CUAVWLink в списке Wi-Fi Windows: выбран модуль CUAVWLink_e68fa3"}),t[5]||(t[5]=e("h3",{id:"_3-запустить-дэшборд",tabindex:"-1"},[a("3. Запустить дэшборд "),e("a",{class:"header-anchor",href:"#_3-запустить-дэшборд","aria-label":'Permalink to "3. Запустить дэшборд"'},"​")],-1)),t[6]||(t[6]=e("p",null,[a("Запустите приложение из таблицы: на компьютере панель откроется в браузере, на Android — внутри приложения. Если браузер не открылся, перейдите на "),e("a",{href:"http://localhost:8080",target:"_blank",rel:"noreferrer"},"http://localhost:8080"),a(" на том же компьютере. При запросе брандмауэра Windows разрешите приложению сетевой доступ для Wi-Fi. Если данные не появляются, нажмите на индикатор подключения вверху и выберите "),e("code",null,"auto"),a(", нужный USB-порт или UDP для Wi-Fi.")],-1)),r(d,{name:"am_can_logger_user_guide_dashboard.webp",alt:"Дэшборд AM CAN logger: состояние сверху, записи слева и текущие показания справа"}),t[7]||(t[7]=o('<p><strong>Сверху</strong> показаны подключение и состояние регистратора, <strong>слева</strong> — записи на карте и компьютере, <strong>справа</strong> — графики загрузки шин, записи на карту и вибраций. Над графиками находится поле для отметок событий. Подробности интерфейса, выбора подключения и завершения приложения — в <a href="./dashboard">руководстве по панели</a>.</p><h2 id="проверка-работы-и-хода-записи" tabindex="-1">Проверка работы и хода записи <a class="header-anchor" href="#проверка-работы-и-хода-записи" aria-label="Permalink to &quot;Проверка работы и хода записи&quot;">​</a></h2><p>После подключения к дэшборду проверьте три признака:</p><ol><li><strong>Состояние записи в верхней панели.</strong> Наведите указатель на индикатор с показаниями <code>fr/s</code> и <code>KiB/s</code>: откроется окно состояния. Проверьте поток записи на карту, наличие свободного места и отсутствие ошибок <code>write errors</code> и потерь кадров. Для каждой подключённой активной CAN-шины должны поступать кадры (<code>fr/s</code> больше нуля).</li><li><strong>Текущая сессия в списке слева.</strong> На вкладке <code>On the card</code> рядом с последней записью должна отображаться зелёная метка <code>recording</code>.</li><li><strong>Обновление графиков справа.</strong> В блоке <code>LIVE</code> периодически появляются новые показания загрузки шин, записи на SD-карту и вибраций. Если графики не обновляются, проверьте, что не включена пауза.</li></ol>',4)),r(d,{name:"am_can_logger_recording_status.webp",alt:"Всплывающее окно состояния записи: поток на карту, состояние CAN1 и CAN2, потери, свободное место и ошибки записи"}),t[8]||(t[8]=e("p",null,[a("На этом примере журнал ULog пишется на карту, но CAN-кадры ещё не поступают: "),e("code",null,"0 fr/s"),a(", "),e("code",null,"detecting the bitrate"),a(" и "),e("code",null,"A bus is quiet"),a(". Если подключённая шина станка должна передавать данные, проверьте её подключение и дождитесь определения скорости; один только поток ULog не подтверждает запись CAN-трафика.")],-1)),r(d,{name:"am_can_logger_recording_session.webp",alt:"Последняя сессия на вкладке On the card отмечена зелёной меткой recording"}),t[9]||(t[9]=o('<p>Повторяйте проверку во время работы: метка <code>recording</code> подтверждает текущую запись, а окно состояния позволяет заметить потери кадров и ошибки записи на карту.</p><h2 id="фиксация-событии-через-дэшборд" tabindex="-1">Фиксация событий через дэшборд <a class="header-anchor" href="#фиксация-событии-через-дэшборд" aria-label="Permalink to &quot;Фиксация событий через дэшборд&quot;">​</a></h2><p>Во время записи фиксируйте все наблюдаемые события: переключения тумблеров, запуск и остановку двигателя, начало и окончание движения, наращивание става и другие операции станка. Метки связывают действия оператора с изменениями CAN-трафика и вибраций: при разборе записи по ним можно определить назначение сообщений и отдельных полей пакетов протокола.</p><p>В правой части дэшборда, в блоке <code>LIVE</code> на вкладке <code>Charts</code>, отображаются графики загрузки шин, записи на SD-карту и метрика вибрации. Над графиками находится поле <code>Event marker</code> для комментария к временной метке и кнопка <code>Mark</code> для её отправки.</p><h3 id="как-поставить-метку" tabindex="-1">Как поставить метку <a class="header-anchor" href="#как-поставить-метку" aria-label="Permalink to &quot;Как поставить метку&quot;">​</a></h3><ol><li>Перед началом действия введите в поле <code>Event marker</code> короткое описание того, что произойдёт.</li><li>Нажмите <code>Mark</code> и дождитесь сообщения о подтверждении метки регистратором.</li><li>Выполните действие; его завершение или переход к следующему этапу отметьте отдельным комментарием.</li></ol>',6)),r(d,{name:"am_can_logger_event_entry.webp",alt:"Поле ввода комментария к событию над графиками LIVE и кнопка Mark"}),t[10]||(t[10]=o('<p>Пишите конкретно: какой орган управления переключается, в какое положение и какая операция начинается или заканчивается. Если событие уже произошло, укажите это в комментарии: метка фиксирует момент её отправки, а не задним числом время действия.</p><table tabindex="0"><thead><tr><th>Событие</th><th>Пример комментария</th></tr></thead><tbody><tr><td>Перед началом движения</td><td>«Сейчас начнём движение»</td></tr><tr><td>Остановка станка</td><td>«Движение завершено, станок остановлен»</td></tr><tr><td>Переключение тумблера</td><td>«Переключаем тумблер освещения в положение ВКЛ»</td></tr><tr><td>Начало наращивания става</td><td>«Проводим процесс наращивания става»</td></tr><tr><td>Окончание наращивания става</td><td>«Наращивание става завершено»</td></tr></tbody></table><h3 id="как-проверить-метку" tabindex="-1">Как проверить метку <a class="header-anchor" href="#как-проверить-метку" aria-label="Permalink to &quot;Как проверить метку&quot;">​</a></h3><p>Внесённые метки отображаются на временной шкале графиков как пронумерованные вертикальные отметки. На скриншоте ниже метка № 1 находится у правого края графиков, рядом с текущим моментом <code>now</code>. По мере продолжения записи она смещается влево; если метка вышла за видимый интервал, выберите больший диапазон времени над графиками.</p>',4)),r(d,{name:"am_can_logger_event_on_charts.webp",alt:"Метка события № 1 на временной шкале графиков загрузки CAN и записи на SD-карту"}),t[11]||(t[11]=e("p",null,"Метки сохраняются на регистраторе вместе с сессией: в журнале ULog и в файле событий рядом с записью CAN. Это позволяет сопоставлять комментарии с кадрами при последующем анализе, даже после закрытия дэшборда.",-1))])}const m=n(s,[["render",h]]);export{b as __pageData,m as default};
